// Данные: готовый отчёт QA-N16-51da2a-2049 (business testim, есть транскрипт и запись). Только чтение → @prod-safe.
import * as path from 'path';
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { openWithApi } from '../support/api';
import { listCandidates } from '../candidates/hiring-support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

const HASH = '#0eafd1 · #db84adc6ceaedbdac00eafd1';
const CANDIDATE = process.env.QA_0EAFD1_CANDIDATE || 'QA-N16-51da2a-2049';

type Json = Record<string, any>;

const VARIANTS: { key: string; title: string; mutate: (j: Json) => void; text: string; transcriptShown: boolean }[] = [
  {
    key: 'A',
    title: 'упал только отчёт (транскрипт и запись есть)',
    mutate: (j) => {
      j.report.status = 'generation_error';
      j.report.analysis_ready_at = null;
    },
    text: 'לא הצלחנו להפיק את הדוח של השיחה. התמלול וההקלטה של השיחה נשמרו, ואפשר לקרוא ולהאזין להם כאן.',
    transcriptShown: true,
  },
  {
    key: 'B',
    title: 'транскрипт упал (transcription_status = failed)',
    mutate: (j) => {
      j.report.status = 'generation_error';
      j.report.analysis_ready_at = null;
      j.report.transcript_ready_at = null;
      if (j.attempt) j.attempt.transcription_status = 'failed';
      j.transcript = null;
    },
    text: 'התמלול של השיחה נכשל, ולכן גם הדוח לא הופק. ההקלטה נשמרה ואפשר להאזין לה כאן.',
    transcriptShown: false,
  },
  {
    key: 'C',
    title: 'транскрипт не завершён (transcription_status = null)',
    mutate: (j) => {
      j.report.status = 'generation_error';
      j.report.analysis_ready_at = null;
      j.report.transcript_ready_at = null;
      if (j.attempt) j.attempt.transcription_status = null;
      j.transcript = null;
    },
    text: 'לא הצלחנו להפיק את הדוח של השיחה, והתמלול שלה לא הושלם. ההקלטה נשמרה ואפשר להאזין לה כאן.',
    transcriptShown: false,
  },
  {
    key: 'D',
    title: 'нет записи (транскрипт есть)',
    mutate: (j) => {
      j.report.status = 'generation_error';
      j.report.analysis_ready_at = null;
      j.recording = null;
    },
    text: 'לא הצלחנו להפיק את הדוח של השיחה. התמלול של השיחה נשמר, ואפשר לקרוא אותו כאן.',
    transcriptShown: true,
  },
];

async function candidateIdByName(page: Page, name: string): Promise<string> {
  const api = await openWithApi(page, '/candidates');
  const found = (await listCandidates(api)).filter((c) => c.full_name === name);
  expect(found, `кандидат «${name}» не найден в list_candidates (QA-данные testim)`).toHaveLength(1);
  return found[0].id;
}

test.describe(`Отчёт — текст «שגיאה בהפקת דוח» по состоянию транскрипта и записи (${HASH})`, () => {
  for (const v of VARIANTS) {
    test(`вариант ${v.key}: ${v.title} — текст ошибки соответствует состоянию @desktop @prod-safe ${HASH}`, async ({ page }) => {
      const id = await candidateIdByName(page, CANDIDATE);
      await page.route('**/rest/v1/rpc/get_candidate_report', async (route) => {
        const res = await route.fetch();
        const body = await res.json();
        const row = Array.isArray(body) ? body[0] : body;
        if (row?.report) v.mutate(row);
        await route.fulfill({ response: res, json: body });
      });
      await page.goto(`/candidates/${id}/report`);

      // Источник: «מה רצוי» #0eafd1 — сообщение описывает, что именно сохранилось (варианты подтверждены пользователем 21.10).
      const error = page.getByTestId('report-error');
      await expect(error).toBeVisible({ timeout: 30_000 });
      await expect(error).toContainText(v.text);
      await expect(error.getByRole('link', { name: 'פנייה לתמיכה' })).toBeVisible();

      if (v.transcriptShown) {
        // Сообщение обещает «אפשר לקרוא … כאן» — транскрипт на странице есть, слов о сбое транскрипта нет.
        await expect(page.getByRole('heading', { name: 'תמלול' })).toBeVisible();
        await expect(error).not.toContainText('נכשל');
        await expect(error).not.toContainText('לא הושלם');
      }
    });
  }
});
